using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using HauntedFish.BossFight;
// OUTSIDE ASSETS, NOT APPLIED. Invoke only in a later exclusive native window.
public static class BossOpaqueFramingRefinement {
 public static void ApplyAfterGrant(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)throw new Exception("Exclusive idle native grant required");var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/BossFight.unity"||scene.isDirty)throw new Exception("Clean owned Boss scene required");var manager=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<BossArenaManager>(true)).Single();var ms=new SerializedObject(manager);var view=(BossArenaView)ms.FindProperty("_Views").objectReferenceValue;var vs=new SerializedObject(view);var rig=(BossSegmentedRig)vs.FindProperty("_GhostFraming").objectReferenceValue;view.Select(BossViewerSide.Fish,true);var camera=view.CurrentCamera;camera.aspect=16f/9f;view.Fit();
 // Preserve table framing and physics. Hide the head artwork's intrinsic cropped lower edge behind far rail.
 var activeHead=rig.GetComponentsInChildren<SpriteRenderer>(true).Single(r=>r.name=="Head"&&r.gameObject.activeInHierarchy);var head=Pixels(activeHead,camera);float rail=camera.WorldToViewportPoint(new Vector3(1000,1.72f,5.65f)).y;float derivative=VerticalDerivative(activeHead.transform.position,camera);float delta=(rail-.006f-head.yMin)/derivative;if(Mathf.Abs(delta)>1.4f)throw new Exception("Unexpected head/rail alignment; inspect authored position before changing");rig.transform.position+=Vector3.up*delta;
 // Compress tentacle artwork around its authored hinge; keep pivot/world X, arm-root attachments and animation.
 foreach(var arm in rig.GetComponentsInChildren<SpriteRenderer>(true).Where(r=>r.name!="Head"&&r!=rig.ShadowSource)) {for(int pass=0;pass<4;pass++){var bounds=Pixels(arm,camera);if(bounds.yMax<=.90f)break;var pivot=camera.WorldToViewportPoint(arm.transform.position).y;float ratio=Mathf.Clamp((.90f-pivot)/Mathf.Max(.01f,bounds.yMax-pivot),.72f,.98f);var scale=arm.transform.localScale;scale.y*=ratio;arm.transform.localScale=scale;}}
 if(Pixels(activeHead,camera).yMin>rail+.01f)throw new Exception("Intrinsic lower artwork cut remains exposed");foreach(var arm in rig.GetComponentsInChildren<SpriteRenderer>(true).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r!=rig.ShadowSource))if(Pixels(arm,camera).yMax>1.01f)throw new Exception("Active opaque art still clipped; leave scene unsaved for inspection");EditorSceneManager.MarkSceneDirty(scene); // Explicit native capture and review before SaveScene; no automatic persistent save.
 }
 static float VerticalDerivative(Vector3 world,Camera camera){float value=camera.WorldToViewportPoint(world+Vector3.up*.1f).y-camera.WorldToViewportPoint(world).y;if(Mathf.Abs(value)<.00001f)throw new Exception("Camera has no vertical projection derivative");return value/.1f;}
 static Rect Pixels(SpriteRenderer renderer,Camera camera){var sprite=renderer.sprite;if(!sprite)throw new Exception("Missing authored sprite");string path=AssetDatabase.GetAssetPath(sprite.texture);var texture=new Texture2D(2,2,TextureFormat.RGBA32,false);try{if(!texture.LoadImage(File.ReadAllBytes(path)))throw new Exception("PNG could not decode");var pixels=texture.GetPixels32();var rect=sprite.rect;float minX=float.PositiveInfinity,minY=minX,maxX=float.NegativeInfinity,maxY=maxX;for(int y=(int)rect.y;y<rect.yMax;y+=4)for(int x=(int)rect.x;x<rect.xMax;x+=4){if(pixels[y*texture.width+x].a<64)continue;var local=new Vector3((x-rect.x-sprite.pivot.x)/sprite.pixelsPerUnit,(y-rect.y-sprite.pivot.y)/sprite.pixelsPerUnit,0);if(renderer.flipX)local.x=-local.x;if(renderer.flipY)local.y=-local.y;var point=camera.WorldToViewportPoint(renderer.transform.TransformPoint(local));minX=Mathf.Min(minX,point.x);maxX=Mathf.Max(maxX,point.x);minY=Mathf.Min(minY,point.y);maxY=Mathf.Max(maxY,point.y);}if(float.IsInfinity(minX))throw new Exception("No opaque art pixels");return Rect.MinMaxRect(minX,minY,maxX,maxY);}finally{UnityEngine.Object.DestroyImmediate(texture);}}
}
